print("zod3 .ip() 3d62::9037%1 ->", zod3.string().ip().safeParse("3d62::9037%1").success);
print("zod3 .ip() ::%1 ->", zod3.string().ip().safeParse("::%1").success);
print("zod3 .ip() fe80::1 ->", zod3.string().ip().safeParse("fe80::1").success);

for (const ip of ["fe80::1%eth0", "::%1", "2001:db8::ff00:42:8329%25"]) {
  print("signup ip", ip, "| oracle:", JSON.stringify(oracle.parseSignup(baseSignup({ip}))), "| main:", JSON.stringify(main.parseSignup(baseSignup({ip}))));
}
for (const h of ["2459::52d2%lo0", "fe80::1%eth0"]) {
  print("config host", h, "| oracle:", JSON.stringify(oracle.parseConfig(baseConfig({hosts:[h]}))), "| main:", JSON.stringify(main.parseConfig(baseConfig({hosts:[h]}))));
}

print("timeout Infinity | oracle:", JSON.stringify(oracle.parseConfig(baseConfig({timeoutMs: Infinity}))), "| main:", JSON.stringify(main.parseConfig(baseConfig({timeoutMs: Infinity}))));
