print("age 1e21 | oracle:", JSON.stringify(oracle.parseSignup(baseSignup({age:1e21}))), "| main:", JSON.stringify(main.parseSignup(baseSignup({age:1e21}))));

const urls = [" https://example.com", "https://example.com\n", "https://example.com", "https://example.com/", "http://Example.COM/A?x=1", "https://example.com/p%2Fq", "https://exämple.com/ü", "https://example.com/a//b/../c"];
for (const u of urls) {
  const a = oracle.parseSignup(baseSignup({website:u}));
  const b = main.parseSignup(baseSignup({website:u}));
  print("url", JSON.stringify(u), "oracle:", a.ok ? JSON.stringify(a.value.website) : "REJECT " + JSON.stringify(a.problems), "main:", b.ok ? JSON.stringify(b.value.website) : "REJECT " + JSON.stringify(b.problems));
}

const multi = baseSignup({email:"nope", plan:"gold", age:1e21, ip:"fe80::1%eth0"});
print("multi signup | oracle:", JSON.stringify(oracle.parseSignup(multi)), "| main:", JSON.stringify(main.parseSignup(multi)));
const mc = {hosts:["fe80::1%eth0","nope"], timeoutMs: Infinity, port:"80"};
print("multi config | oracle:", JSON.stringify(oracle.parseConfig(mc)), "| main:", JSON.stringify(main.parseConfig(mc)));

