print("--- A: zone-index set comparison ---");
const zoned=["fe80::1%eth0","fe80::%25","2001:db8::ff00:42:8329%25","3d62::9037%1","::%1","305b:7432:e22d:4c35:1962:71c6:ed4d:69ae%1","2459::52d2%lo0"];
let o3=0,m4=0;
for(const a of zoned){const z=zod3.string().ip().safeParse(a).success;const ms=main.parseSignup(S({ip:a})).ok;const mc=main.parseConfig({hosts:[a]}).ok;const oc=oracle.parseConfig({hosts:[a]}).ok;if(z)o3++;if(ms)m4++;print("zone",a,"| zod3.ip:",z,"| oracleConfig:",oc,"| mainSignup:",ms,"| mainConfig:",mc);}
print("zoned accepted by zod3:",o3,"of",zoned.length,"| accepted by main:",m4,"of",zoned.length);

print("--- B: Infinity reachability ---");
