for(const u of [" https://example.com","https://example.com\n","https://example.com","https://example.com/","http://Example.COM/A?x=1","https://example.com/a//b/../c"]){const o=oracle.parseSignup(S({website:u})),m=main.parseSignup(S({website:u}));print("url",JSON.stringify(u),"| oracle:",o.ok?JSON.stringify(o.value.website):"REJECT","| main:",m.ok?JSON.stringify(m.value.website):"REJECT");}

