print("88 verdicts both reject:",!oracle.parseSignup(c1).ok&&!main.parseSignup(c1).ok,!oracle.parseSignup(c2).ok&&!main.parseSignup(c2).ok,!oracle.parseSignup(c3).ok&&!main.parseSignup(c3).ok);

